   AND destino.cco_anio = origen.anio AND destino.cco_mes = origen.mes AND destino.cco_id_tipo = origen.id_tipo
WHEN MATCHED THEN
    UPDATE SET cco_nombre = origen.nombre, cco_monto = origen.monto, cco_pct = origen.pct
WHEN NOT MATCHED THEN
    INSERT (cco_id_negocio, cco_tienda_codigo, cco_anio, cco_mes, cco_id_tipo, cco_nombre, cco_monto, cco_pct)
    VALUES (origen.id_negocio, origen.tienda_codigo, origen.anio, origen.mes, origen.id_tipo, origen.nombre, origen.monto, origen.pct);
GO

